SELECT o.org_id, o.org_code, o.org_name, o.org_type, o.parent_org_id, o.org_level, o.org_path, o.status_cd, o.sort_order, COALESCE(m.member_count, 0) as member_count, CASE WHEN EXISTS(SELECT 1 FROM bt_organization c WHERE c.parent_org_id = o.org_id) THEN 1 ELSE 0 END as has_children FROM bt_organization o LEFT JOIN ( SELECT org_id, COUNT(1) as member_count FROM bt_organization_member WHERE status_cd = '00A' GROUP BY org_id ) m ON o.org_id = m.org_id WHERE o.space_id = #{spaceId}
AND (o.org_id = #{rootOrgId} OR o.org_path LIKE CONCAT((SELECT org_path FROM bt_organization WHERE org_id = #{rootOrgId}), '%'))
AND o.org_level <= #{maxLevel}
AND o.status_cd = '00A' ORDER BY o.org_level ASC, o.sort_order ASC, o.org_id ASC

SELECT o.org_id, o.org_code, o.org_name, o.org_type, o.parent_org_id, o.org_level, o.org_path, o.status_cd, o.sort_order, COALESCE(m.member_count, 0) as member_count, CASE WHEN EXISTS(SELECT 1 FROM bt_organization c WHERE c.parent_org_id = o.org_id) THEN 1 ELSE 0 END as has_children FROM bt_organization o LEFT JOIN ( SELECT org_id, COUNT(1) as member_count FROM bt_organization_member WHERE status_cd = '00A' GROUP BY org_id ) m ON o.org_id = m.org_id WHERE o.space_id = #{spaceId}
AND o.org_name LIKE
#{orgName}
AND (o.org_id = #{rootOrgId} OR o.org_path LIKE CONCAT((SELECT org_path FROM bt_organization WHERE org_id = #{rootOrgId}), '%'))
AND o.org_level <= #{maxLevel}
AND o.status_cd = '00A' ORDER BY o.org_level ASC, o.sort_order ASC, o.org_id ASC

